var t=`1028-cao-lau`;var a=`world-1028`;var n=`VN`;var s=`southeast-asia`;var r=4;var o=124;var l={en:`Cao Lau`,ua:`Као лау`};var d={en:`Cao Lau is a dish from Vietnam prepared with pork belly, light soy sauce, garlic, rice noodles. This is a home-scale version with measured ingredients in the individual steps where they are used. Ordinary rice noodles replace Hoi An specialty cao lầu noodles; the signature texture cannot be reproduced exactly.`,ua:`Као лау, страва кухні країни В'єтнам, яку готують із таких продуктів: свиняча грудинка, світлий соєвий соус, часник, рисова локшина. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Звичайна рисова локшина замінює особливу локшину као лау з Хойана; точну текстуру не відтворити.`};var u=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 45 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 45 хвилин.`,t:[`marinating`],m:45,i:[[`pork-belly`,650,`g`],[`light-soy-sauce`,50,`ml`],[`garlic`,3,`clove`],[`star-anise`,1,`pcs`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 65 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 65 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:65,i:[[`water`,420,`ml`],[`white-granulated-sugar`,18,`g`]]},{en:`Cook the listed ingredients in simmering water for about 9 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 9 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:9,i:[[`rice-noodles`,420,`g`],[`water`,1100,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`lettuce`,170,`g`],[`mung-bean-sprouts`,200,`g`],[`cilantro`,24,`g`],[`peanut`,100,`g`]]}];var g={slug:t,id:a,country:`VN`,region:s,servings:4,minutes:124,title:l,text:d,steps:u};export{n as country,g as default,a as id,o as minutes,s as region,r as servings,t as slug,u as steps,d as text,l as title};